library(shiny)

# 1. Intentamos descargar la versión oficial de WebAssembly
# Esto evita usar la carpeta de tu PC que es para Windows
if (!require("RNASeqPower", quietly = TRUE)) {
  webr::install("RNASeqPower", repos = c("https://repo.r-wasm.org/", "https://bioc.r-wasm.org/latest"))
}

library(RNASeqPower)

# --- UI ---
ui <- fluidPage(
  titlePanel("Calculadora RNA-Seq (Versión WebAssembly)"),
  sidebarLayout(
    sidebarPanel(
      numericInput("depth", "Depth:", 100), 
      numericInput("cv", "CV:", 0.7), 
      numericInput("effect", "Effect:", 1.25), 
      numericInput("power", "Power:", 0.8), 
      numericInput("alpha", "Alpha:", 0.05),
      actionButton("btn_calcular", "CALCULAR")
    ),
    mainPanel(
      h3("Resultado:"),
      uiOutput("resultado")
    )
  )
)

# --- SERVER ---
server <- function(input, output) {
  calculo <- eventReactive(input$btn_calcular, {
    req(input$depth, input$cv, input$effect, input$alpha, input$power)
    RNASeqPower::rnapower(
      depth = input$depth, 
      cv = input$cv, 
      effect = input$effect, 
      alpha = input$alpha, 
      power = input$power
    )
  })

  output$resultado <- renderUI({
    if (input$btn_calcular == 0) return("Pulsa Calcular.")
    res <- calculo()
    h1(paste(ceiling(res), "sujetos por grupo"))
  })
}

shinyApp(ui, server)
